package com.rumitx.app.repeaters;
import android.app.*;import android.os.*;import android.content.*;import android.location.Location;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
import org.mapsforge.map.android.view.MapView;import org.mapsforge.map.android.graphics.AndroidGraphicFactory;import org.mapsforge.map.android.util.AndroidUtil;import org.mapsforge.map.reader.MapFile;import org.mapsforge.map.layer.cache.TileCache;import org.mapsforge.map.layer.overlay.Marker;import org.mapsforge.core.model.*;import org.mapsforge.map.rendertheme.internal.MapsforgeThemes;
public final class RepeaterMapActivity extends FeatureActivity {
 private LinearLayout root;private MapView map;private RepeaterDatabase db;private TextView info;private File current;private final ArrayList<Marker> pins=new ArrayList<>();private final Handler ui=new Handler();private final ExecutorService worker=Executors.newSingleThreadExecutor();private int generation;private boolean centered;private final Runnable refresh=()->loadPins();
 protected void onCreate(Bundle state){super.onCreate(state);AndroidGraphicFactory.createInstance(getApplication());db=new RepeaterDatabase(this);root=column();root.addView(label("REPEATER MAP / OFFLINE VECTOR",20));info=label("Copy a Mapsforge .map file to /sdcard/RumiTX/maps, or choose a local map. No network is required to view maps.",13);root.addView(info);locationState=label("Own-position and distance unavailable until Location is enabled.",12);root.addView(locationState);LinearLayout bar=new LinearLayout(this);bar.addView(button("Choose map",this::choose),new LinearLayout.LayoutParams(0,-2,1));bar.addView(button("Location",()->{centered=false;locationFeature();}),new LinearLayout.LayoutParams(0,-2,1));bar.addView(button("Download",()->RepeaterDownloads.mapDialog(this)),new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);root.addView(label("Map data © OpenStreetMap contributors · mapsforge.org · Map-file attribution may also apply.",10));setContentView(root);File[] files=new File(getFilesDir(),"maps").listFiles(f->f.getName().endsWith(".map"));if(files!=null&&files.length>0)load(files[0]);}
 private void choose(){new AlertDialog.Builder(this).setItems(new String[]{"Choose .map file with Files","USB maps folder"},(d,n)->{if(n==0){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,45);}else storage(this::usb);}).show();}
 private void usb(){File dir=new File(android.os.Environment.getExternalStorageDirectory(),"RumiTX/maps");dir.mkdirs();File[] files=dir.listFiles(f->f.isFile()&&f.getName().endsWith(".map"));if(files==null||files.length==0){message("No .map files in /sdcard/RumiTX/maps. Copy your offline map there using USB.");return;}Arrays.sort(files);String[] names=new String[files.length];for(int i=0;i<files.length;i++)names[i]=files[i].getName();new AlertDialog.Builder(this).setItems(names,(d,n)->load(files[n])).show();}
 private void load(File f){try{MapFile data=new MapFile(f);if(map!=null){root.removeView(map);map.destroyAll();}pins.clear();centered=false;current=f;map=new MapView(this);map.setClickable(true);map.getMapScaleBar().setVisible(true);map.setBuiltInZoomControls(true);map.getModel().mapViewPosition.setZoomLevelMin((byte)3);map.getModel().mapViewPosition.setZoomLevelMax((byte)18);TileCache cache=AndroidUtil.createTileCache(this,"repeater-map",map.getModel().displayModel.getTileSize(),1f,map.getModel().frameBufferModel.getOverdrawFactor());map.getLayerManager().getLayers().add(AndroidUtil.createTileRendererLayer(cache,map.getModel().mapViewPosition,data,MapsforgeThemes.DEFAULT));LatLong center=data.boundingBox().getCenterPoint();map.getModel().mapViewPosition.setCenter(center);map.getModel().mapViewPosition.setZoomLevel((byte)9);map.getModel().mapViewPosition.addObserver(()->{ui.removeCallbacks(refresh);ui.postDelayed(refresh,250);});root.addView(map,new LinearLayout.LayoutParams(-1,0,1));info.setText(f.getName()+" · tap a repeater pin for its full profile");ui.postDelayed(refresh,500);}catch(Exception e){message("Map could not be opened: "+e.getMessage());}}
 protected void onPosition(Location p){if(map!=null&&p!=null){if(!centered){centered=true;map.getModel().mapViewPosition.setCenter(new LatLong(p.getLatitude(),p.getLongitude()));}ui.post(refresh);}}
 private void loadPins(){if(map==null||worker.isShutdown()||isFinishing()||map.getWidth()==0)return;final MapView view=map;BoundingBox b=view.getBoundingBox();final int ticket=++generation;worker.execute(()->{try{List<Repeater> rows=db.box(b.minLatitude,b.minLongitude,b.maxLatitude,b.maxLongitude,500);runOnUiThread(()->{if(ticket!=generation||map!=view||isFinishing())return;for(Marker pin:pins){view.getLayerManager().getLayers().remove(pin);pin.onDestroy();}pins.clear();for(Repeater r:rows){Marker pin=new Marker(new LatLong(r.latitude,r.longitude),icon(r.status.equals("off-air")?0xffff2244:0xff00f0ff),0,0){public boolean onTap(LatLong ll,Point center,Point point){if(contains(center,point,view)){RepeaterProfiles.show(RepeaterMapActivity.this,r,db,()->ui.post(refresh));return true;}return false;}};pins.add(pin);view.getLayerManager().getLayers().add(pin);}if(position!=null){Marker me=new Marker(new LatLong(position.getLatitude(),position.getLongitude()),icon(0xffffb000),0,0);pins.add(me);view.getLayerManager().getLayers().add(me);}info.setText(current.getName()+" · "+rows.size()+" visible repeater pins"+(rows.size()==500?" · zoom in to see more":""));});}catch(Exception e){runOnUiThread(()->{if(!isFinishing())info.setText("Map records unavailable: "+e.getMessage());});}});}
 private org.mapsforge.core.graphics.Bitmap icon(int color){int size=(int)(48*getResources().getDisplayMetrics().density);android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(size,size,android.graphics.Bitmap.Config.ARGB_8888);android.graphics.Canvas c=new android.graphics.Canvas(bitmap);android.graphics.Paint p=new android.graphics.Paint(3);p.setColor(0xcc061318);c.drawCircle(size/2f,size/2f,size*.25f,p);p.setColor(color);p.setStyle(android.graphics.Paint.Style.STROKE);p.setStrokeWidth(size*.04f);c.drawCircle(size/2f,size/2f,size*.24f,p);p.setStyle(android.graphics.Paint.Style.FILL);c.drawCircle(size/2f,size/2f,size*.07f,p);return AndroidGraphicFactory.convertToBitmap(new android.graphics.drawable.BitmapDrawable(getResources(),bitmap));}
 protected void onActivityResult(int req,int result,Intent intent){super.onActivityResult(req,result,intent);if(req==45&&result==RESULT_OK&&intent!=null&&intent.getData()!=null){info.setText("Copying and validating offline map…");worker.execute(()->{File dir=new File(getFilesDir(),"maps");dir.mkdirs();File tmp=new File(dir,"selected.map.partial"),dest=new File(dir,"selected.map");try(InputStream in=getContentResolver().openInputStream(intent.getData());OutputStream out=new FileOutputStream(tmp)){RepeaterDownloads.copy(in,out,2L*1024*1024*1024);out.flush();MapFile probe=new MapFile(tmp);probe.close();if(dest.exists()&&!dest.delete())throw new IOException("Cannot replace selected map");if(!tmp.renameTo(dest))throw new IOException("Cannot save map");runOnUiThread(()->load(dest));}catch(Exception e){tmp.delete();runOnUiThread(()->message("Map import failed: "+e.getMessage()));}});}}
 protected void onDestroy(){ui.removeCallbacksAndMessages(null);generation++;worker.shutdownNow();if(map!=null)map.destroyAll();new Thread(()->{try{worker.awaitTermination(10,TimeUnit.SECONDS);}catch(Exception ignored){}db.close();}).start();super.onDestroy();}
}
